1	export interface Item {
2	  readonly type: string;
3	  readonly material?: string;
4	  readonly enchantment?: number;
5	  readonly cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  readonly op: "quote";
10	  readonly items: readonly Item[];
11	}
12	
13	export interface Damage {
14	  readonly itemType: string;
15	  readonly amount: number;
16	}
17	
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	export interface ClaimStep {
24	  readonly op: "claim";
25	  readonly policy: number;
26	  readonly incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  readonly yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  readonly customer: Customer;
37	  readonly steps: readonly Step[];
38	}
39	
40	export interface QuoteResult {
41	  readonly premium: number;
42	}
43	
44	export interface ClaimResult {
45	  readonly payout: number;
46	  readonly remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  readonly results: readonly StepResult[];
53	}
54	
55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const itemBasePremiumOf = (item: Item): number =>
68	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
69	
70	const BLOCK_PREMIUM = 60;
71	const BLOCK_SIZE = 3;
72	
73	const itemsGroupedByType = (
74	  items: readonly Item[],
75	): readonly (readonly Item[])[] => [
76	  ...items
77	    .reduce(
78	      (groups, item) =>
79	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
80	      new Map<string, readonly Item[]>(),
81	    )
82	    .values(),
83	];
84	
85	const groupBasePremiumOf = (group: readonly Item[]): number =>
86	  group.length === BLOCK_SIZE
87	    ? BLOCK_PREMIUM
88	    : sumOf(group, itemBasePremiumOf);
89	
90	const CURSED_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
92	const HIGH_ENCHANTMENT_THRESHOLD = 5;
93	
94	const cursedSurchargeOf = (item: Item): number =>
95	  item.cursed === true ? itemBasePremiumOf(item) * CURSED_SURCHARGE_RATE : 0;
96	
97	const highEnchantmentSurchargeOf = (item: Item): number =>
98	  item.enchantment === HIGH_ENCHANTMENT_THRESHOLD
99	    ? itemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
100	    : 0;
101	
102	const itemSurchargeOf = (item: Item): number =>
103	  cursedSurchargeOf(item) + highEnchantmentSurchargeOf(item);
104	
105	const policyBasePremiumOf = (items: readonly Item[]): number =>
106	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
107	
108	const policySurchargeOf = (items: readonly Item[]): number =>
109	  sumOf(items, itemSurchargeOf);
110	
111	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
112	
113	const firstInsuranceSurchargeOf = (items: readonly Item[]): number =>
114	  policyBasePremiumOf(items) * FIRST_INSURANCE_SURCHARGE_RATE;
115	
116	const premiumBeforeFeeOf = (items: readonly Item[]): number =>
117	  policyBasePremiumOf(items) +
118	  policySurchargeOf(items) +
119	  firstInsuranceSurchargeOf(items);
120	
121	const PROCESSING_FEE = 5;
122	
123	const quotePremiumOf = (items: readonly Item[]): number =>
124	  Math.ceil(premiumBeforeFeeOf(items) + PROCESSING_FEE);
125	
126	export const runScenario = (scenario: Scenario): ScenarioResult => ({
127	  results: [
128	    { premium: quotePremiumOf((scenario.steps[0] as QuoteStep).items) },
129	  ],
130	});
